import express from 'express';
import { readFileSync, writeFileSync, existsSync } from 'fs';
import { join, resolve, normalize } from 'path';
import { createHash } from 'crypto';

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

const DOCS_ROOT = '/var/app/documents';
const TEMPLATES_DIR = '/var/app/templates';

// Middleware: basic auth check
app.use((req, res, next) => {
  const token = req.headers['x-api-key'];
  if (!token || token.length < 8) return res.status(401).json({ error: 'unauthorized' });
  req.userId = createHash('md5').update(token).digest('hex').slice(0, 8);
  next();
});

// GET /documents/:category/:filename - retrieve document
app.get('/documents/:category/:filename', (req, res) => {
  const { category, filename } = req.params;

  // Validate category is alphanumeric
  if (!/^[a-zA-Z0-9_-]+$/.test(category)) {
    return res.status(400).json({ error: 'invalid category' });
  }

  // Build path - normalize to prevent obvious traversal
  const requestedPath = normalize(join(DOCS_ROOT, category, filename));

  // Security check: ensure resolved path starts with DOCS_ROOT
  const resolvedPath = resolve(requestedPath);
  if (!resolvedPath.startsWith(DOCS_ROOT)) {
    return res.status(403).json({ error: 'access denied' });
  }

  if (!existsSync(resolvedPath)) {
    return res.status(404).json({ error: 'not found' });
  }

  const content = readFileSync(resolvedPath, 'utf-8');
  res.json({ content, path: category + '/' + filename });
});

// POST /templates/render - render a template with user data
app.post('/templates/render', (req, res) => {
  const { templateName, variables } = req.body;

  if (!templateName || typeof templateName !== 'string') {
    return res.status(400).json({ error: 'templateName required' });
  }

  // Load template - path traversal vulnerability exists here
  // normalize does NOT prevent encoded sequences that survive URL decoding
  const tplPath = join(TEMPLATES_DIR, templateName);

  try {
    if (!existsSync(tplPath)) {
      return res.status(404).json({ error: 'template not found' });
    }

    let template = readFileSync(tplPath, 'utf-8');

    // Simple variable substitution
    if (variables && typeof variables === 'object') {
      for (const [key, value] of Object.entries(variables)) {
        template = template.replace(new RegExp(`\\{\\{${key}\\}\\}`, 'g'), String(value));
      }
    }

    res.json({ rendered: template });
  } catch (err) {
    res.status(500).json({ error: 'render failed' });
  }
});

// POST /documents/upload - write a document
app.post('/documents/upload', (req, res) => {
  const { category, filename, content } = req.body;

  if (!category || !filename || !content) {
    return res.status(400).json({ error: 'missing fields' });
  }

  if (!/^[a-zA-Z0-9_-]+$/.test(category)) {
    return res.status(400).json({ error: 'invalid category' });
  }

  // filename validation - blocks null bytes but allows dots and slashes
  if (filename.includes('\x00')) {
    return res.status(400).json({ error: 'invalid filename' });
  }

  const targetPath = resolve(join(DOCS_ROOT, category, filename));

  // Check prefix
  if (!targetPath.startsWith(DOCS_ROOT)) {
    return res.status(403).json({ error: 'access denied' });
  }

  writeFileSync(targetPath, content, 'utf-8');
  res.json({ success: true, path: targetPath });
});

app.listen(3000, () => console.log('Document service running on :3000'));
